def evaluate_gram(twice_level: int, momentum: float) -> np.ndarray:
    """Evaluate a normalized, parity-ordered Gram matrix."""
    try:
        evaluator = _GRAM_EVALUATORS[int(twice_level)]
    except KeyError as exc:
        raise ValueError(f'no generated Gram kernel at twice-level {twice_level}') from exc
    return evaluator(momentum)

def evaluate_vertex_parts(
    component: str,
    left_twice_level: int,
    right_twice_level: int,
    left_momentum: float,
    external_weight: complex,
    right_momentum: float,
) -> np.ndarray:
    """Return sign-even/sign-odd normalized Ward matrices."""
    key = (str(component), int(left_twice_level), int(right_twice_level))
    try:
        evaluator = _VERTEX_EVALUATORS[key]
    except KeyError as exc:
        raise ValueError(f'no generated Ramond vertex kernel for {key}') from exc
    return evaluator(left_momentum, external_weight, right_momentum)

